    async def form_fields(self, session_id: str, **args: Any) -> dict[str, Any]:
        return await self.run(session_id, "form_fields", **args)

    async def screenshot(self, session_id: str, **args: Any) -> dict[str, Any]:
        return await self.run(session_id, "screenshot", **args)

    async def execute(self, session_id: str, code: str, **args: Any) -> dict[str, Any]:
        """Run JavaScript in the page. `code` is a function body, so use `return` to get a value back as `result`."""
        return await self.run(session_id, "execute", code=code, **args)

