class _AsyncSessions:
    def __init__(self, client: AsyncSteerpane) -> None:
        self._c = client

    async def list(self, *, status: str | None = None, profile_id: str | None = None, q: str | None = None, project_id: str | None = None,
             limit: int | None = None, cursor: str | None = None) -> Page[Session]:
        return await self._c.request("GET", "/v1/sessions", params=_clean({"status": status, "profile_id": profile_id, "q": q, "project_id": project_id, "limit": limit, "cursor": cursor}))

    async def create(self, *, idempotency_key: str | None = None, **config: Any) -> Session:
        """Start a browser. `config` takes the session fields in the API docs, such as `initial_url`, `profile_id`, `auto_close`, `timeout_min`."""
        return await self._c.request("POST", "/v1/sessions", json=_clean(config), headers={"Idempotency-Key": idempotency_key or str(uuid.uuid4())})

    async def get(self, session_id: str) -> Session:
        return await self._c.request("GET", f"/v1/sessions/{_seg(session_id)}")

    async def wait_until_ready(self, session_id: str, *, timeout_s: float = 90, poll_s: float = 0.5) -> Session:
        """Wait for the browser to leave `starting`. Raises if it ends instead, or doesn't start in time."""
        deadline = time.monotonic() + timeout_s
        while True:
            session = await self.get(session_id)
            status = session.get("status")
            if status in ENDED_SESSION_STATUSES:
                raise SteerpaneError(f"Session {session_id} ended before it was ready: {session.get('error_message') or status}")
            if status != "starting":
                return session
            if time.monotonic() >= deadline:
                raise SteerpaneError(f"Session {session_id} was still starting after {timeout_s:.0f} s")
            await asyncio.sleep(poll_s)

    async def stop(self, session_id: str) -> Session:
        return await self._c.request("POST", f"/v1/sessions/{_seg(session_id)}/stop")

    async def delete(self, session_id: str) -> None:
        await self._c.request("DELETE", f"/v1/sessions/{_seg(session_id)}")

    async def keepalive(self, session_id: str) -> Session:
        return await self._c.request("POST", f"/v1/sessions/{_seg(session_id)}/keepalive")

    async def takeover(self, session_id: str) -> Session:
        return await self._c.request("POST", f"/v1/sessions/{_seg(session_id)}/takeover")

    async def handback(self, session_id: str, *, outcome: str | None = None, note: str | None = None) -> Session:
        """Give control back. `outcome` is `done` or `not_done`, and the waiting agent receives it with the note."""
        return await self._c.request("POST", f"/v1/sessions/{_seg(session_id)}/handback", json=_clean({"outcome": outcome, "note": note}))

    async def request_help(self, session_id: str, *, reason: str, message: str = "") -> dict[str, Any]:
        """Ask a person for help. The agent goes on hold, and `agent.human_help_requested` fires."""
        return await self._c.request("POST", f"/v1/sessions/{_seg(session_id)}/help-requests", json={"reason": reason, "message": message})

    async def wait_for_human(self, session_id: str, request_id: str = "latest", *, timeout_s: float = 30) -> HumanResult:
        """Long-poll until the human hands back. `status` is `handed_back`, `timeout` (call again) or `stopped`."""
        return await self._c.request("GET", f"/v1/sessions/{_seg(session_id)}/help-requests/{_seg(request_id)}/wait", params={"timeout_s": timeout_s},
                               timeout=max(self._c.timeout, timeout_s + 30))

    async def events(self, session_id: str, *, limit: int | None = None, cursor: str | None = None) -> Page[dict[str, Any]]:
        return await self._c.request("GET", f"/v1/sessions/{_seg(session_id)}/events", params=_clean({"limit": limit, "cursor": cursor}))

    async def files(self, session_id: str) -> Any:
        return await self._c.request("GET", f"/v1/sessions/{_seg(session_id)}/files")

    async def zip_files(self, session_id: str) -> dict[str, Any]:
        """Pack what the session downloaded into one ZIP in the file store."""
