class _AsyncRuns:
    """Hosted agent runs. These use your organization's own model key."""

    def __init__(self, client: AsyncSteerpane) -> None:
        self._c = client

    async def create(self, task: str, *, idempotency_key: str | None = None, **fields: Any) -> AgentRun:
        """`fields`: `profile_id`, `agent_id`, `model`, `max_steps`, `max_cost_usd`, `max_duration_s`, `result_schema`, `variables`, `project_id`."""
        return await self._c.request("POST", "/v1/agents/runs", json={"task": task, **_clean(fields)}, headers={"Idempotency-Key": idempotency_key or str(uuid.uuid4())})

    async def get(self, run_id: str) -> AgentRun:
        return await self._c.request("GET", f"/v1/agents/runs/{_seg(run_id)}")

    async def list(self, *, status: str | None = None, agent_id: str | None = None, project_id: str | None = None, limit: int | None = None, cursor: str | None = None) -> Page[AgentRun]:
        return await self._c.request("GET", "/v1/agents/runs", params=_clean({"status": status, "agent_id": agent_id, "project_id": project_id, "limit": limit, "cursor": cursor}))

    async def messages(self, run_id: str) -> Page[dict[str, Any]]:
        return await self._c.request("GET", f"/v1/agents/runs/{_seg(run_id)}/messages")

    async def cancel(self, run_id: str) -> AgentRun:
        return await self._c.request("POST", f"/v1/agents/runs/{_seg(run_id)}/cancel")

    async def wait(self, run_id: str, *, timeout_s: float = 600, poll_s: float = 2) -> AgentRun:
        """Poll until the run finishes. Returns the run whatever its outcome, so check `status`."""
        deadline = time.monotonic() + timeout_s
        while True:
            run = await self.get(run_id)
            if run.get("status") in ENDED_RUN_STATUSES:
                return run
            if time.monotonic() >= deadline:
                raise SteerpaneError(f"Run {run_id} had not finished after {timeout_s:.0f} s (status {run.get('status')})")
            await asyncio.sleep(poll_s)


class _AsyncFiles:
    def __init__(self, client: AsyncSteerpane) -> None:
        self._c = client

    async def upload(self, file: str | Path | bytes, *, name: str | None = None, mime: str | None = None, ttl_hours: int | None = None) -> StoredFile:
        """Store a file. The result's `id` goes straight into `actions.upload_file(session_id, file_id=...)`."""
        if isinstance(file, bytes):
            content, filename = file, name or "file"
        else:
            content, filename = Path(file).read_bytes(), name or Path(file).name
        form = _clean({"name": name, "ttl_hours": ttl_hours})
        return await self._c.request("POST", "/v1/files", data={k: str(v) for k, v in form.items()},
                               files={"file": (filename, content, mime or "application/octet-stream")})

    async def create_upload_url(self, name: str, *, mime: str | None = None, size_bytes: int | None = None, ttl_hours: int | None = None) -> UploadUrl:
        return await self._c.request("POST", "/v1/files/uploads", json=_clean({"name": name, "mime": mime, "size_bytes": size_bytes, "ttl_hours": ttl_hours}))

    async def list(self, *, source: str | None = None, session_id: str | None = None, q: str | None = None, limit: int | None = None, cursor: str | None = None) -> Page[StoredFile]:
        return await self._c.request("GET", "/v1/files", params=_clean({"source": source, "session_id": session_id, "q": q, "limit": limit, "cursor": cursor}))

    async def get(self, file_id: str) -> StoredFile:
        return await self._c.request("GET", f"/v1/files/{_seg(file_id)}")

    async def download(self, file_id: str) -> bytes:
        """The file's bytes. On S3 storage the API redirects to a presigned URL, which is fetched without your token."""
        return await self._c.request_bytes(f"/v1/files/{_seg(file_id)}/content")

    async def delete(self, file_id: str) -> None:
        await self._c.request("DELETE", f"/v1/files/{_seg(file_id)}")


